// 只导入类型。`import type` 在编译后会被擦掉，不会把 next 的类型定义打进运行时包。
import type { NextConfig } from "next";
// Sentry 官方的 Next.js 适配器。它会在构建阶段上传 source map，并把错误监控接进这份配置。
import { withSentryConfig } from "@sentry/nextjs";

/**
 * Fracture Recovery Companion（骨折康复陪伴）的 Next.js 16 站点配置。
 *
 * 这个文件在执行 `next dev` / `next build` / `next start` 时由 Node 读取，
 * 改完需要重启开发服务器才会生效。
 *
 * 当前范围对应 Story 1.1 的营销站骨架：安全响应头、图片优化、
 * Turbopack 占位，以及“有 DSN 才启用”的 Sentry。
 * 业务图片域名（例如 Cloudflare Stream 缩略图）不在这里写死，
 * 等后续真正要用远程图片的 story 再加 `images.remotePatterns`。
 */
// 显式标成 NextConfig：字段名写错时，编辑器会立刻报类型错误。
const nextConfig: NextConfig = {
  // 开发模式打开 React Strict Mode。渲染和部分 effect 会被故意执行两次，用来暴露不干净的副作用；生产构建不会双次执行。
  reactStrictMode: true,

  // `next/image` 的优化规则。只影响走 Image 组件或 `/_next/image` 的图，不改变普通 `<img>`。
  images: {
    // 浏览器接受哪种就用哪种，数组里靠前的优先。AVIF 更小，WebP 兼容面更广，都不支持时回退原图。
    formats: ["image/avif", "image/webp"],
    // 大图 srcset 的宽度档，单位是像素。布局接近整屏宽时，Next 从这里挑最接近设备宽度的一张。
    // 官方默认还有 3840；这里去掉了 4K 档，超宽屏少生成一档超大图。
    deviceSizes: [640, 750, 828, 1080, 1200, 1920, 2048],
    // 小图宽度档。`sizes` 表明图片只占屏幕一小块时用这些宽度，避免用上面的大档去放大一张小图标。
    imageSizes: [16, 32, 48, 64, 96, 128, 256, 384],
  },

  // 仍处在实验阶段、但本项目选择打开的编译选项。
  experimental: {
    // 把桶文件导入改写成深层路径，例如 `import { X } from "lucide-react"` 不再把整包图标拖进客户端。
    optimizePackageImports: [
      // 图标库是典型的大桶文件，不优化的话很容易整包进 bundle。
      "lucide-react",
      // Radix 的 Slot 同样通过桶入口导出，这里让打包器只保留用到的那一块。
      "@radix-ui/react-slot",
    ],
  },

  // Next.js 16 起，dev 和 build 默认走 Turbopack。空对象表示“使用 Turbopack，且没有额外 alias / loader”。
  // 下面仍保留了 webpack 函数：Turbopack 构建不会执行它；Sentry 上传 source map 或显式 `--webpack` 时才走 webpack。
  // 写上这个空配置，是为了消掉“自定义了 webpack、却没有 turbopack 配置”的警告。
  turbopack: {},

  // 关掉响应头 `X-Powered-By: Next.js`，避免主动告诉外界站点框架。默认是开启的。
  poweredByHeader: false,
  // 由 Next 服务器给响应做 gzip。前面如果已经有 CDN 或反向代理在压缩，两边不要重复开。
  compress: true,
  // 为页面生成 ETag。内容没变时浏览器可以拿 304，不必重新下载整页。生产模式默认就是 true，这里写出来是为了明确意图。
  generateEtags: true,

  // 只有 Docker 构建（环境变量 DOCKER_BUILD=true）才输出 standalone。
  // standalone 会在 `.next/standalone` 里放一份精简的 server.js 和 node_modules，镜像不用再装完整依赖。
  // 本地和 Vercel 不设这个变量，保持 undefined，继续用普通 `.next` 输出。
  output: process.env.DOCKER_BUILD === "true" ? "standalone" : undefined,

  // 请求还没进页面之前就做跳转。可以写成 async，是因为规则允许在运行时动态计算；这里的列表是固定的。
  async redirects() {
    // 返回跳转规则数组。没有命中的请求会继续走正常路由。
    return [
      {
        // `/:path*` 匹配所有路径，包含多级目录；`*` 表示这一段可以空，所以首页 `/` 也会命中。
        source: "/:path*",
        // `has` 是额外条件。下面的 host 不匹配时，这条规则不生效，因此主域名不会把自己再跳一次。
        has: [
          {
            // 按请求头 Host 判断，而不是按路径判断。
            type: "host",
            // 只处理带 www 的主机名。
            value: "www.fracturerecoverycoach.com",
          },
        ],
        // 跳到不带 www 的规范域名，并用 `:path*` 把原路径原样带上。查询串 Next 会默认保留。
        destination: "https://fracturerecoverycoach.com/:path*",
        // true 表示 308 永久跳转，浏览器和搜索引擎会记住。以后如果要改目标，旧的 308 可能仍被缓存。
        permanent: true,
      },
    ];
  },

  // 给命中的路径追加 HTTP 响应头。一条请求可以同时命中多条 source，头会合并；同名时后面的规则覆盖前面的。
  async headers() {
    return [
      {
        // `(.*)` 匹配全部路径，营销页、接口、图片优化地址都会带上下面这组安全头。
        source: "/(.*)",
        headers: [
          // 允许浏览器提前解析后续会用到的域名（dns-prefetch）。值为 on/off。
          { key: "X-DNS-Prefetch-Control", value: "on" },
          // 禁止浏览器凭内容猜 MIME。服务器说是文本，就不能被当成脚本执行。
          { key: "X-Content-Type-Options", value: "nosniff" },
          // 只允许同源页面用 iframe 嵌本站，降低被别的网站做点击劫持的可能。现代替代写法是 CSP 的 frame-ancestors。
          { key: "X-Frame-Options", value: "SAMEORIGIN" },
          // 旧版 IE / 老 Chrome 的 XSS 过滤器。`mode=block` 表示一旦觉得像反射型 XSS 就停止渲染。新浏览器已忽略此头，不能替代输出转义。
          { key: "X-XSS-Protection", value: "1; mode=block" },
          // 同源请求带完整 Referer；跨站 HTTPS 只带协议+主机+端口，不带路径和查询串。避免把 URL 上的敏感参数漏给第三方。
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
        ],
      },
      {
        // 只匹配 `/static/...`。对应仓库里 `public/static` 下的文件；当前没有这类文件，规则先留着。
        source: "/static/(.*)",
        headers: [
          {
            // public：CDN 可以缓存。31536000 秒 = 365 天。immutable：缓存期内刷新页面也不重新验证。
            // 只适合“URL 变了内容才变”的文件。如果往 `/static` 放不带内容哈希的文件，更新后用户会长时间看到旧文件。
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
        ],
      },
      {
        // `/_next/image` 是 `next/image` 的优化接口，后面可能带查询参数，所以用 `(.*)`。
        source: "/_next/image(.*)",
        headers: [
          {
            // 优化后的图缓存 7 天（604800 秒）。过期后的 1 天（86400 秒）内仍可先返回旧图，同时在后台重新生成。
            key: "Cache-Control",
            value: "public, max-age=604800, stale-while-revalidate=86400",
          },
        ],
      },
    ];
  },

  // 自定义 webpack。第一个参数是 Next 已经组装好的配置，改完必须 return。第二个参数能区分环境和打包目标。
  // Turbopack 构建不会走这个函数，见上面的 turbopack 说明。
  webpack: (config, { dev, isServer }) => {
    // `dev` 为 true 表示 `next dev`。`isServer` 为 true 表示正在打服务端包。这里只处理生产环境的浏览器包。
    if (!dev && !isServer) {
      // 整体替换 optimization 时先展开原配置，避免把 Next 已有的分包、压缩选项弄丢。
      config.optimization = {
        ...config.optimization,
        // 标记每个模块里真正被用到的导出，方便后面的压缩步骤删掉没人引用的代码。生产模式 webpack 默认已开启。
        usedExports: true,
        // 尊重依赖 package.json 里的 `sideEffects` 标记：标成无副作用的文件，在导出都没用到时可以整文件丢掉。
        sideEffects: true,
      };
    }
    // webpack 要求把配置对象返回；返回 undefined 会导致构建用上空配置。
    return config;
  },
};

// 传给 withSentryConfig 的第二参数，只影响“构建时如何上传和处理 source map”，不是运行时的采样率。
const sentryConfig = {
  // 构建日志里不打印 Sentry 插件的常规输出。上传失败时该出现的错误仍会失败，不会被这行吞掉。
  silent: true,
  // Sentry 组织的 slug，来自构建机器的环境变量。不要把真实值写进这个文件。
  org: process.env.SENTRY_ORG,
  // 该组织下的项目 slug。和 org、authToken 一起才能把 source map 传到正确的项目。
  project: process.env.SENTRY_PROJECT,
  // 上传 source map 用的令牌。next.config 在 Node 里读取，光写在这里不会自动进浏览器包；仍然不要提交到 Git。
  authToken: process.env.SENTRY_AUTH_TOKEN,
  // 扩大客户端 source map 的上传范围，让更多分包的堆栈能还原到源码。上传体积和时间会增加。
  widenClientFileUpload: true,
  // 上传完成后不要把 source map 暴露给浏览器，避免线上能直接看到原始源码。
  hideSourceMaps: true,
  // 从客户端包里去掉 Sentry 的调试 logger，减小体积，也避免用户控制台刷 SDK 内部日志。
  disableLogger: true,
};

// 两个 DSN 都是空字符串或未设置时，条件为假。空字符串在 JS 里是 falsy。
// SENTRY_DSN 给服务端用；NEXT_PUBLIC_SENTRY_DSN 给浏览器 SDK 用，只有带 NEXT_PUBLIC_ 前缀才会被打进客户端代码。
export default process.env.SENTRY_DSN || process.env.NEXT_PUBLIC_SENTRY_DSN
  // 配了任意一个 DSN：把上面的 nextConfig 交给 Sentry 包装后再导出。Next 实际加载的是包装后的配置。
  ? withSentryConfig(nextConfig, sentryConfig)
  // 没配 DSN：原样导出。本地可以不申请 Sentry 就启动。
  : nextConfig;

